"""
    Get indices of elements in an array which satisfies func
    >>> indices([1, 2, 3, 4], lambda x: x>2)
    [2, 3]
    >>> indices([1, 2, 3, 4], lambda x: x==2.5)
    []
    >>> indices([1, 2, 3, 4], lambda x: x>1 and x<=3)
    [1, 2]
    >>> indices([1, 2, 3, 4], lambda x: x in [2, 4])
    [1, 3]
    """
def indices(a: Any, func: Any) -> object {
    return [
        i
        for (i, val) in enumerate(a)
        if func(val)
    ];
}

"""Say if an optional argument is plainly present"""
def opt_in_argv_tail(argv_tail: Any, concise: Any, mnemonic: Any) -> object {
    assert (concise or mnemonic);
    if concise {
        assert (concise.startswith("-") and not concise.startswith("--"));
    }
    if mnemonic {
        assert (mnemonic.startswith("--") and not mnemonic.startswith("---"));
    }
    for arg in argv_tail {
        if (mnemonic.startswith(arg) and (arg > "--")) {
            return True;
        }
        if (arg.startswith(concise) and not arg.startswith("--")) {
            return True;
        }
    }
    return False;
}

